def make_penalty(lam):
    def loss(x):return x*x+lam*abs(x)
    return loss
print(make_penalty(.2)(3.))

def safe_divide(a,b):
    if b==0:raise ZeroDivisionError('zero divisor')
    return a/b
try:print(safe_divide(1,0))
except ZeroDivisionError as e:print(type(e).__name__)

